#!/usr/bin/env bash
# The stamps of the perf_rdma vFPGA in XSIM (tb_perf_rdma_stamp). Uses the
# package and the user-logic wrapper generated by a perf_rdma build (BUILD,
# default build_oct15_rdma_qdma); the wrapper includes ../src/vfpga_top.svh.
set -u
cd "$(dirname "$0")"
if ! command -v xvlog >/dev/null 2>&1; then
    exec xilinx-shell "$(pwd)/$(basename "$0")" "$@"
fi
COYOTE_ROOT=../../../..
BUILD=${BUILD:-../build_oct15_rdma_qdma}
GEN=$BUILD/example_09_perf_rdma_config_0/user_c0_0/hdl
[ -f "$GEN/lynx_pkg.sv" ] || { echo "ERROR: $GEN/lynx_pkg.sv not found (BUILD=<a perf_rdma build dir>)"; exit 1; }
SRCS="$GEN/lynx_pkg.sv $COYOTE_ROOT/hw/hdl/pkg/axi_intf.sv $COYOTE_ROOT/hw/hdl/pkg/lynx_intf.sv \
      ../src/hdl/stamp_rec.sv ../src/hdl/stamp_csr.sv sim_ila_perf_rdma.sv $GEN/wrappers/user_logic_c0_0.sv"
mkdir -p work && cd work
xvlog -sv $(for f in $SRCS; do echo ../$f; done) ../tb_perf_rdma_stamp.sv -i ../../src -i ../$COYOTE_ROOT/hw/hdl/pkg \
    > xvlog.log 2>&1 || { tail -30 xvlog.log; echo "COMPILE FAILED"; exit 1; }
xelab -debug typical tb_perf_rdma_stamp -s sim > xelab.log 2>&1 || { tail -30 xelab.log; echo "ELAB FAILED"; exit 1; }
xsim -R sim > xsim.log 2>&1
grep -E "^(st|FAIL)" xsim.log
grep -q "TB PASS (tb_perf_rdma_stamp)" xsim.log && echo "PASS: tb_perf_rdma_stamp" || { echo "FAIL: tb_perf_rdma_stamp (see hw/tb/work/xsim.log)"; exit 1; }
